import { assertHmacParams } from './utils/assertHash.mjs'
import { toWebCryptoDigestType } from './utils/browserHashTools.mjs'
import { fromUint8orString, combineHashInput } from './utils/input.mjs'
import { fromUint8Super } from './utils/output.mjs'

const crypto = globalThis.crypto

export async function hmac(type, secret, data, form = 'buffer') {
  assertHmacParams(type, secret, form)
  secret = fromUint8orString(secret) // eslint-disable-line no-param-reassign
  data = combineHashInput(data) // eslint-disable-line no-param-reassign

  const hashAlgo = toWebCryptoDigestType(type)
  if (!hashAlgo) throw new Error('Unexpected algo') // assertHmac already caught this, but for coherence
  const algo = { name: 'HMAC', hash: hashAlgo }
  const key = await crypto.subtle.importKey('raw', secret, algo, false, ['sign'])
  const result = await crypto.subtle.sign(algo, key, data)
  return fromUint8Super(new Uint8Array(result), form)
}

